set -e
echo "Listing repo files:";
find /src/mupdf -maxdepth 3 -type f -print | sed -n '1,200p'

echo "\nSearching for relevant symbols...";
grep -Rn "pdf_resolve_indirect_chain" /src/mupdf || true;
grep -Rn "pdf_resolve_indirect" /src/mupdf || true;
grep -Rn "pdf_cache_object" /src/mupdf || true;

echo "\nShow matches for pdf_resolve_indirect and surrounding lines";
grep -Rn "pdf_resolve_indirect" /src/mupdf -n -n || true

