        pdf_obj *resolved = pdf_resolve_indirect(ctx, ref);
        if (!resolved)
        {
            if (kept)
                pdf_drop_obj(ctx, kept);
            return NULL;
        }

        if (kept)
            pdf_drop_obj(ctx, kept);
        kept = pdf_keep_obj(ctx, resolved);

        /* Continue resolving from the newly kept object. */
        ref = kept;
    }

    if (kept)
        return kept;

    return ref;
}

